import com.mybatisflex.spring.service.impl.ServiceImpl;
import com.mybatisflex.core.paginate.Page;
import java.util.List;
import static ${config.modelPackage}.table.${modelName}TableDef.${entityTableDef};

/**
 * $!table.comment 服务层实现。
 *
 * @author $author
 * @since $since
 */
@Service
public class ${implName} extends ServiceImpl<${mapperName},${modelName}> implements ${interfaceName} {
    private final static ${modelName}TableDef t = ${entityTableDef};
    private final SqlOperators sqlOperators = SqlOperators.of(${modelName}::getTitle, SqlOperator.LIKE);

    @Override
    public Page<${modelName}> selectListByPage(Page<${modelName}> page, ${modelName} entity) {
        QueryWrapper query = QueryWrapper.create(entity, sqlOperators).from(${modelName}.class);
        query.where(t.CREATE_TIME.ge(DateUtils.parseDate(entity.getParams().get("beginTime"))))
                .and(t.CREATE_TIME.le(DateUtils.parseDate(entity.getParams().get("endTime"))));
        return this.page(page, query);
    }

    @Override
    public List<${modelName}> selectList(${modelName} entity) {
        QueryWrapper query = QueryWrapper.create(entity, sqlOperators).from(${modelName}.class);
        return this.list(query);
    }
}

